    /// <summary>Gets the value of the leaf at a <see cref="UnionLeafInfo"/> index. The value is boxed. It is null when the leaf is not set.</summary>
    public object? GetLeaf(int index)
    {
        return index switch
        {
            0 => Display.Visible,
            1 => Display.Opacity,
            2 => Layout.Alignment.Container,
            3 => Layout.Alignment.Horizontal,
            4 => Layout.Alignment.Vertical,
            5 => Layout.Alignment.Order,
            6 => Layout.Width,
            7 => Layout.Height,
            8 => Layout.Spacing,
            9 => Layout.Padding.Left,
            10 => Layout.Padding.Right,
            11 => Layout.Padding.Top,
            12 => Layout.Padding.Bottom,
            13 => Layout.Inset.Left,
            14 => Layout.Inset.Right,
            15 => Layout.Inset.Top,
            16 => Layout.Inset.Bottom,
            17 => Layout.Margins.Left,
            18 => Layout.Margins.Right,
            19 => Layout.Margins.Top,
            20 => Layout.Margins.Bottom,
            21 => Text.Alignment.Container,
            22 => Text.Alignment.Horizontal,
            23 => Text.Alignment.Vertical,
            24 => Text.Alignment.Order,
            25 => Text.Font,
            26 => Text.Color,
            27 => Text.WrapMode,
            28 => Text.Elide,
            29 => Icon.Alignment.Container,
            30 => Icon.Alignment.Horizontal,
            31 => Icon.Alignment.Vertical,
            32 => Icon.Alignment.Order,
            33 => Icon.Width,
            34 => Icon.Height,
            35 => Icon.Name,
            36 => Icon.Source,
            37 => Icon.Color,
            38 => Background.Color,
            39 => Background.Image.Source,
            40 => Background.Image.Width,
            41 => Background.Image.Height,
            42 => Background.Image.XOffset,
            43 => Background.Image.YOffset,
            44 => Background.Image.Flags,
            45 => Background.Image.MaskColor,
            46 => Border.Left.Size,
            47 => Border.Left.Color,
            48 => Border.Left.Style,
            49 => Border.Right.Size,
            50 => Border.Right.Color,
            51 => Border.Right.Style,
            52 => Border.Top.Size,
            53 => Border.Top.Color,
            54 => Border.Top.Style,
            55 => Border.Bottom.Size,
            56 => Border.Bottom.Color,
            57 => Border.Bottom.Style,
            58 => Outline.Left.Size,
            59 => Outline.Left.Color,
            60 => Outline.Left.Style,
            61 => Outline.Right.Size,
            62 => Outline.Right.Color,
            63 => Outline.Right.Style,
            64 => Outline.Top.Size,
